import { test, expect } from '@playwright/test';

test.describe('Registration Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/registration');
  });

  test('should show error for invalid email format', async ({ page }) => {
    await page.fill(getByLabel('Email'), 'invalid-email');
    await page.click(getByRole('button', { name: 'Submit' }));

    const errorMessage = await page.getByText('Please enter a valid email address.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not show error for valid email format', async ({ page }) => {
    await page.fill(getByLabel('Email'), 'test@example.com');
    await page.click(getByRole('button', { name: 'Submit' }));

    const errorMessage = page.getByText('Please enter a valid email address.');
    await expect(errorMessage).not.toBeVisible();
  });
});
